-- 036: LKav-Ausbau W260 neu: Eisen 15 -> Eisen 20/Lehm 16/Holz 16 -> Katapulte -> Adelshof (Vorgabe Fetteruruk 11.10.).
update public.bau_vorlagen set queue=$q$main:1;farm:1;storage:1;iron:4;wood:1;stone:1;wood:1;stone:1;wood:1;stone:1;main:2;barracks:2;iron:5;wood:5;stone:4;main:1;farm:1;storage:2;market:1;main:4;storage:1;hide:2;main:1;smith:1;wall:1;farm:3;main:1;smith:4;barracks:3;stable:1;storage:1;farm:1;stable:2;market:2;storage:1;hide:3;wall:4;iron:4;storage:1;iron:1;storage:1;iron:1;stone:1;wood:1;farm:1;stone:1;wood:1;farm:1;stone:1;wood:1;farm:1;iron:1;storage:1;stone:1;wood:1;farm:1;iron:1;storage:1;stone:1;wood:1;farm:1;iron:1;stone:1;iron:1;storage:1;farm:1;wood:1;stone:1;iron:1;storage:1;wood:1;farm:1;stone:1;wood:1;stone:1;smith:7;garage:5;main:7;farm:1;main:3;market:7;smith:4;storage:1;smith:1;storage:1;farm:1;smith:1;storage:1;smith:1;storage:1;smith:1;storage:1;snob:1$q$, beschreibung=$d$Fortsetzung von LKav-Push W260 (enthält deren Schritte). Reihenfolge nach Vorgabe 11.10.: 1) Eisen bis 15 (Eisen fehlt für LKav), 2) Eisen 20, Lehm 16, Holz 16 gemeinsam (jeweils günstigste Stufe je Mehrproduktion, Eisen doppelt gewichtet), 3) Katapulte: Schmiede 12, Werkstatt 1-5 (Katapult = Werkstatt 2 + Schmiede 12, Standardwerte; Katapult von Hand erforschen), 4) Adelshof: HG 20, Markt 10, Schmiede 20, Speicher 17 (fasst die 25k Lehm), Adelshof 1. Durchgehend: Speicher fasst mind. 10 Std. Produktion und den nächsten Auftrag (nichts läuft über), Bauernhof hält 15 % frei für Truppen. Mit Truppen-Vorrang (bis 50 LKav) und Truppenvorlage (LKav 200) kombinieren.$d$ where team_id is null and lower(name)=lower('LKav-Ausbau W260');
